package Google::Cloud::Dialogflow::V2::Participant::ParticipantsClient;

=pod

=head2 Service Client: Google::Cloud::Dialogflow::V2::Participant::ParticipantsClient

Client stub representing the remote C<Participants> gRPC service. Delegates call dispatching to L<Google::gRPC::Client>.

=head3 target

The endpoint target address. Defaults to C<dialogflow.googleapis.com:443>.

=head3 credentials

The authentication credentials provider. Defaults to application default credentials via L<Google::Auth>.

=cut

