Type: C<String>

The article URI.

=item * C<< $msg->snippets() >> / C<< $msg->snippets($value) >>

Type: C<String>

Article snippets.

=item * C<< $msg->confidence() >> / C<< $msg->confidence($value) >>

Type: C<Float>

Article match confidence.
The system's confidence score that this article is a good match for this
conversation, as a value from 0.0 (completely uncertain) to 1.0
(completely certain).

=item * C<< $msg->metadata() >> / C<< $msg->metadata($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2::Participant::ArticleAnswer::MetadataEntry>)

