=head2 Google::Cloud::Dialogflow::V2::Participant::AnnotatedMessagePart

Represents a part of a message possibly annotated with an entity. The part
can be an entity or purely a part of the message between two entities or
message start/end.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->text() >> / C<< $msg->text($value) >>

Type: C<String>

A part of a message possibly annotated with an entity.

=item * C<< $msg->entity_type() >> / C<< $msg->entity_type($value) >>

Type: C<String>

The [Dialogflow system entity
type](https://cloud.google.com/dialogflow/docs/reference/system-entities)
of this message part. If this is empty, Dialogflow could not annotate the
phrase part with a system entity.

=item * C<< $msg->formatted_value() >> / C<< $msg->formatted_value($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Value>)

The [Dialogflow system entity formatted value
](https://cloud.google.com/dialogflow/docs/reference/system-entities) of
this message part. For example for a system entity of type
`@sys.unit-currency`, this may contain:
<pre>
{
  "amount": 5,
  "currency": "USD"
}
</pre>

=back

=head2 Google::Cloud::Dialogflow::V2::Participant::MessageAnnotation

Represents the result of annotation for the message.

