=over 4

=item * C<< $msg->parts() >> / C<< $msg->parts($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2::Participant::AnnotatedMessagePart>)

The collection of annotated message parts ordered by their
position in the message. You can recover the annotated message by
concatenating [AnnotatedMessagePart.text].

=item * C<< $msg->contain_entities() >> / C<< $msg->contain_entities($value) >>

Type: C<Bool>

Indicates whether the text message contains entities.

=back

=head2 Google::Cloud::Dialogflow::V2::Participant::SuggestionInput

Represents the action to take for a tool call that requires confirmation.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->answer_record() >> / C<< $msg->answer_record($value) >>

Type: C<String>

Required. Format: `projects/<Project ID>/locations/<Location
ID>/answerRecords/<Answer Record ID>`
The answer record associated with the tool call.

=item * C<< $msg->parameters() >> / C<< $msg->parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Optional. Parameters to be used for the tool call.  If not provided, the
tool will be called without any parameters.

=item * C<< $msg->action() >> / C<< $msg->action($value) >>

Type: C<Enum> (L<Google::Cloud::Dialogflow::V2::SuggestionInput::Action>)

Optional. The type of action to take with the tool.

=item * C<< $msg->send_time() >> / C<< $msg->send_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Optional. Time when the current suggest input is sent. For tool calls, this
timestamp (along with the answer record) will be included in the
corresponding tool call result so that it can be identified.

=back

=head3 Enum: SuggestionInput::Action

=over 4

=item * C<ACTION_UNSPECIFIED> => C<0>

=item * C<CANCEL> => C<1>

=item * C<REVISE> => C<2>

=item * C<CONFIRM> => C<3>

=back

=head2 Google::Cloud::Dialogflow::V2::Participant::AssistQueryParameters

Represents the parameters of human assist query.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->documents_metadata_filters() >> / C<< $msg->documents_metadata_filters($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2::Participant::AssistQueryParameters::DocumentsMetadataFiltersEntry>)

Key-value filters on the metadata of documents returned by article
suggestion. If specified, article suggestion only returns suggested
documents that match all filters in their
[Document.metadata][google.cloud.dialogflow.v2.Document.metadata]. Multiple
values for a metadata key should be concatenated by comma. For example,
filters to match all documents that have 'US' or 'CA' in their market
metadata values and 'agent' in their user metadata values will be
```
documents_metadata_filters {
  key: "market"
  value: "US,CA"
}
documents_metadata_filters {
  key: "user"
  value: "agent"
}
```

=back

