=head2 Google::Cloud::Dialogflow::V2::Participant::SuggestKnowledgeAssistRequest

The request message for
[Participants.SuggestKnowledgeAssist][google.cloud.dialogflow.v2.Participants.SuggestKnowledgeAssist].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The name of the participant to fetch suggestions for.
Format: `projects/<Project ID>/locations/<Location
ID>/conversations/<Conversation ID>/participants/<Participant ID>`.

=item * C<< $msg->latest_message() >> / C<< $msg->latest_message($value) >>

Type: C<String>

Optional. The name of the latest conversation message to compile
suggestions for. If empty, it will be the latest message of the
conversation. Format: `projects/<Project ID>/locations/<Location
ID>/conversations/<Conversation ID>/messages/<Message ID>`.

=item * C<< $msg->context_size() >> / C<< $msg->context_size($value) >>

Type: C<Int32>

Optional. Max number of messages prior to and including
[latest_message][google.cloud.dialogflow.v2.SuggestKnowledgeAssistRequest.latest_message]
to use as context when compiling the suggestion. The context size is by
default 100 and at most 100.

=item * C<< $msg->previous_suggested_query() >> / C<< $msg->previous_suggested_query($value) >>

Type: C<String>

Optional. The previously suggested query for the given conversation. This
helps identify whether the next suggestion we generate is reasonably
different from the previous one. This is useful to avoid similar
suggestions within the conversation.

=back

=head2 Google::Cloud::Dialogflow::V2::Participant::SuggestKnowledgeAssistResponse

The response message for
[Participants.SuggestKnowledgeAssist][google.cloud.dialogflow.v2.Participants.SuggestKnowledgeAssist].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->knowledge_assist_answer() >> / C<< $msg->knowledge_assist_answer($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2::Participant::KnowledgeAssistAnswer>)

Output only. Knowledge Assist suggestion.

=item * C<< $msg->latest_message() >> / C<< $msg->latest_message($value) >>

Type: C<String>

The name of the latest conversation message used to compile suggestion for.
Format: `projects/<Project ID>/locations/<Location
ID>/conversations/<Conversation ID>/messages/<Message ID>`.

=item * C<< $msg->context_size() >> / C<< $msg->context_size($value) >>

Type: C<Int32>

Number of messages prior to and including
[latest_message][google.cloud.dialogflow.v2.SuggestKnowledgeAssistResponse.latest_message]
to compile the suggestion. It may be smaller than the
[SuggestKnowledgeAssistRequest.context_size][google.cloud.dialogflow.v2.SuggestKnowledgeAssistRequest.context_size]
field in the request if there are fewer messages in the conversation.

=item * C<< $msg->additional_suggested_query_results() >> / C<< $msg->additional_suggested_query_results($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2::Participant::KnowledgeAssistAnswer::AdditionalSuggestedQueryResult>)

Optional. The list of additional suggested queries based on the context.
This is used for the cases when we want to generate multiple queries
for a single request.

=back

